import * as Sentry from "@sentry/solid"
import { useMutation } from "@tanstack/solid-query"
import { createIsomorphicFn, createServerFn } from "@tanstack/solid-start"
import { getCookie, setCookie } from "@tanstack/solid-start/server"
import { createContext, useContext } from "solid-js"
import { createStore } from "solid-js/store"
import * as v from "valibot"

import type { JSX } from "solid-js"

export const CookieConsentSchema = v.object({
  accepted: v.number(), // Timestamp of when consent was given, or 0 if not accepted
  necessary: v.literal(true), // Strictly Necessary, always true: theme, auth, settings, etc.
  analytics: v.boolean(), // Analytics, optional: GA4, etc.
  marketing: v.boolean(), // Marketing / Advertising, optional: SharpSpring, etc.
  functional: v.boolean() // Functional / Preferences, optional: enhanced features, etc.
})
export type CookieConsentState = v.InferOutput<typeof CookieConsentSchema>
export type MaybeCookieConsentState = CookieConsentState | undefined

export const COOKIE_CONSENT_NAME = "gc-consent"
export const COOKIE_CONSENT_DURATION = 60 * 60 * 24 * 365 // 1 year
export const DEFAULT_COOKIE_CONSENT: CookieConsentState = {
  accepted: 0,
  necessary: true,
  analytics: false,
  marketing: false,
  functional: false
}

// Mutations
export const saveCookieConsent = createServerFn({ method: "POST" })
  .validator(CookieConsentSchema)
  .handler(({ data }) => {
    const locale = getCookie("locale") || "en-US"
    const timeZone = decodeURIComponent(getCookie("tz") || "UTC")
    const localeDate = new Date().toLocaleString(locale, { timeZone })
    const currentLocalDate = new Date(localeDate)
    const localTimestampInMilliseconds = currentLocalDate.getTime()
    const newCookie: CookieConsentState = {
      accepted: localTimestampInMilliseconds,
      necessary: true,
      analytics: data.analytics,
      marketing: data.marketing,
      functional: data.functional
    }
    setCookie(COOKIE_CONSENT_NAME, JSON.stringify(newCookie), {
      maxAge: COOKIE_CONSENT_DURATION
    })
    return newCookie
  })

export const getCookieConsent = createIsomorphicFn()
  .server((): CookieConsentState => {
    try {
      const settings = getCookie(COOKIE_CONSENT_NAME)
      if (!settings) {
        setCookie(COOKIE_CONSENT_NAME, JSON.stringify(DEFAULT_COOKIE_CONSENT), {
          maxAge: COOKIE_CONSENT_DURATION
        })
        return DEFAULT_COOKIE_CONSENT
      }
      const parsedSettings = JSON.parse(settings) as CookieConsentState
      return parsedSettings
    } catch {
      return DEFAULT_COOKIE_CONSENT
    }
  })
  .client((): CookieConsentState => {
    try {
      const cookie = document.cookie
        .split("; ")
        .find((row) => row.startsWith(`${COOKIE_CONSENT_NAME}=`))
      if (!cookie) return DEFAULT_COOKIE_CONSENT
      const cookieValue = cookie.split("=")[1]
      const parseCookie = JSON.parse(decodeURIComponent(cookieValue))
      const settings = v.parse(CookieConsentSchema, parseCookie)
      return settings
    } catch {
      return DEFAULT_COOKIE_CONSENT
    }
  })

// Context and Provider
export type CookieConsentStateActions = {
  consent: (data: CookieConsentState) => void
}

export type CookieConsentStateContextProvider = [
  CookieConsentState,
  CookieConsentStateActions
]

const CookieConsentStateContext = createContext<CookieConsentStateContextProvider>()

const CookieConsentProvider = (props: { children: JSX.Element }) => {
  const cookieConsentMutation = useMutation(() => ({
    mutationKey: ["save-cookie-consent"],
    mutationFn: saveCookieConsent
  }))
  const [state, setState] = createStore<CookieConsentState>(getCookieConsent())
  const actions: CookieConsentStateActions = {
    consent: (consent: CookieConsentState) => {
      cookieConsentMutation.mutate(
        { data: consent },
        {
          onSuccess: (data) => {
            setState(data)
          },
          onError: (error) => {
            Sentry.logger.warn(
              "CookieConsentProvider cookieConsentMutation error: actions.consent",
              {
                reason: error,
                data: consent
              }
            )
          }
        }
      )
    }
  }
  const store: CookieConsentStateContextProvider = [state, actions]
  return (
    <CookieConsentStateContext.Provider value={store}>
      {props.children}
    </CookieConsentStateContext.Provider>
  )
}

export default CookieConsentProvider

export function useCookieConsentState(): CookieConsentStateContextProvider {
  const ctx = useContext(CookieConsentStateContext)
  if (!ctx) throw new Error("<CookieConsentProvider> not found wrapping the <App />.")
  return ctx
}

import { Field, Form, createForm, setInput, submit } from "@formisch/solid"
import { Link } from "@tanstack/solid-router"
import { batch, createSignal } from "solid-js"

import type { SubmitHandler } from "@formisch/solid"

import {
  CookieConsentSchema,
  useCookieConsentState
} from "@/components/cookie-consent-provider"
import { cn } from "@/lib/utils/tailwind"
import CheckboxSwitchInput from "@/registry/kobalte/form-inputs/checkbox-switch-input"
import HiddenInput from "@/registry/kobalte/form-inputs/hidden-input"
import Cookie from "@/registry/kobalte/icons/svg/cookie"
import { Button } from "@/registry/kobalte/ui/button"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/kobalte/ui/tooltip"

export default function CookieConsentBanner() {
  const [consent, actions] = useCookieConsentState()
  const [showBanner, setShowBanner] = createSignal(consent.accepted === 0)
  const formStore = createForm({
    schema: CookieConsentSchema,
    initialInput: {
      accepted: 0,
      necessary: true,
      analytics: consent.accepted > 0 ? consent.analytics : true,
      marketing: consent.accepted > 0 ? consent.marketing : true,
      functional: consent.accepted > 0 ? consent.functional : true
    },
    validate: "submit",
    revalidate: "input"
  })
  const handleSubmit: SubmitHandler<typeof CookieConsentSchema> = (values) => {
    actions.consent(values)
    setShowBanner(false)
  }
  const updateCookies = (mode: "all" | "none") => {
    if (mode === "all") {
      batch(() => {
        setInput(formStore, { path: ["analytics"], input: true })
        setInput(formStore, { path: ["marketing"], input: true })
        setInput(formStore, { path: ["functional"], input: true })
      })
    } else {
      batch(() => {
        setInput(formStore, { path: ["analytics"], input: false })
        setInput(formStore, { path: ["marketing"], input: false })
        setInput(formStore, { path: ["functional"], input: false })
      })
    }
    submit(formStore)
  }
  const inputClass = "col-span-1 text-center border border-foreground/25 py-2"
  const switchClass = "justify-center items-center"
  return (
    <>
      <Tooltip openDelay={50} placement="right">
        <TooltipTrigger
          id="cookie-consent-trigger"
          tabIndex={!showBanner() ? 1 : undefined}
          as="a"
          class={cn(
            "z-999999 block fixed transition-transform duration-300 cursor-pointer",
            "bottom-4 left-4 size-14 p-2 lg:size-12 lg:bottom-4 lg:left-4",
            "shadow-2xl backdrop-blur-sm border rounded-full bg-white/80 dark:bg-black/80 dark:border-gray-700 dark:text-white",
            !showBanner() ? "translate-y-0" : "translate-y-full"
          )}
          onClick={() => setShowBanner((prev) => !prev)}
          onKeyPress={(e) => {
            if (e.key == "Enter") {
              e.preventDefault()
              setShowBanner((prev) => !prev)
            }
          }}
        >
          <Cookie class="size-full" />
        </TooltipTrigger>
        <TooltipContent>Edit Cookie Preferences</TooltipContent>
      </Tooltip>
      <div
        id="cookie-consent-settings"
        class={cn(
          "z-999999 block fixed bottom-0 left-0 w-full transition-transform duration-300",
          "pt-2 px-3 pb-10 sm:px-2 lg:pb-4",
          "shadow-2xl backdrop-blur-sm bg-white/80 border-t dark:bg-black/80 dark:border-gray-700 dark:text-white",
          showBanner() ? "translate-y-0" : "translate-y-full"
        )}
      >
        <div class={cn("flex flex-col items-center justify-between px-2")}>
          <div class="my-2 prose dark:prose-invert">
            <p class="text-xs">
              <span class="font-bold">We use cookies</span> to personalize your
              experience, provide social media features, and analyze our traffic. We
              also share information about your use of our site with our social media,
              advertising and analytics partners. To learn more about the data we
              collect and how it is used, please visit our{" "}
              <Link
                to={"/policies/$slug"}
                params={{
                  slug: "gc-privacy-policy"
                }}
                reloadDocument={true}
                class="cursor-pointer underline underline-offset-4 hover:text-primary"
              >
                Privacy Policy
              </Link>
              .
            </p>
          </div>
          <Form
            of={formStore}
            onSubmit={handleSubmit}
            class={cn(
              "grid grid-cols-2 xs:grid-cols-4 gap-0 w-full max-w-2xl mt-1 mx-auto"
            )}
          >
            <Field of={formStore} path={["accepted"]}>
              {(field) => (
                <HiddenInput
                  {...field.props}
                  value={field.input}
                  error={field.errors}
                />
              )}
            </Field>
            <Field of={formStore} path={["necessary"]}>
              {(field) => (
                <CheckboxSwitchInput<boolean>
                  {...field.props}
                  label="Necessary"
                  orientation="vertical"
                  name={field.props.name}
                  checked={true}
                  value={true}
                  error={field.errors}
                  onChange={() => field.onInput(true)}
                  onKeyPress={(e) => {
                    if (e.key == "Enter") {
                      e.preventDefault()
                      field.onInput(true)
                    }
                  }}
                  disabled={true}
                  class={inputClass}
                  switchClass={switchClass}
                />
              )}
            </Field>
            <Field of={formStore} path={["analytics"]}>
              {(field) => (
                <CheckboxSwitchInput<boolean>
                  {...field.props}
                  label="Analytics"
                  orientation="vertical"
                  name={field.props.name}
                  checked={field.input ?? true}
                  value={field.input ?? true}
                  error={field.errors}
                  onChange={(v) => field.onInput(v)}
                  onKeyPress={(e) => {
                    if (e.key == "Enter") {
                      e.preventDefault()
                      field.onInput(!field.input)
                    }
                  }}
                  class={inputClass}
                  switchClass={switchClass}
                />
              )}
            </Field>
            <Field of={formStore} path={["marketing"]}>
              {(field) => (
                <CheckboxSwitchInput<boolean>
                  {...field.props}
                  label="Marketing"
                  orientation="vertical"
                  name={field.props.name}
                  checked={field.input ?? true}
                  value={field.input ?? true}
                  error={field.errors}
                  onChange={(v) => field.onInput(v)}
                  onKeyPress={(e) => {
                    if (e.key == "Enter") {
                      e.preventDefault()
                      field.onInput(!field.input)
                    }
                  }}
                  class={inputClass}
                  switchClass={switchClass}
                />
              )}
            </Field>
            <Field of={formStore} path={["functional"]}>
              {(field) => (
                <CheckboxSwitchInput<boolean>
                  {...field.props}
                  label="Functional"
                  orientation="vertical"
                  name={field.props.name}
                  checked={field.input ?? true}
                  value={field.input ?? true}
                  error={field.errors}
                  onChange={(v) => field.onInput(v)}
                  onKeyPress={(e) => {
                    if (e.key == "Enter") {
                      e.preventDefault()
                      field.onInput(!field.input)
                    }
                  }}
                  class={inputClass}
                  switchClass={switchClass}
                />
              )}
            </Field>
          </Form>
          <div
            class={cn(
              "grid grid-col-1 xs:grid-cols-3 gap-2 w-full max-w-2xl mt-2 mx-auto"
            )}
          >
            <Button
              variant="outline"
              class={cn("col-span-1")}
              onClick={() => updateCookies("none")}
            >
              Deny
            </Button>
            <Button
              variant="secondary"
              disabled={formStore.isSubmitting || !formStore.isValid}
              onClick={() => submit(formStore)}
              class={cn("col-span-1")}
            >
              Accept
            </Button>
            <Button
              variant="default"
              disabled={formStore.isSubmitting || !formStore.isValid}
              onClick={() => updateCookies("all")}
              class={cn("col-span-1")}
            >
              Accept All
            </Button>
          </div>
        </div>
      </div>
    </>
  )
}
